#include<stdio.h>
int main(int argc, char *argv[])
{
	long int a,b,s,i,j,k;
	long int dist;

	if(scanf("%ld %ld %ld", &a, &b, &s) != 3)
		return 1;

	if(a < 0) a = -a;
	if(b < 0) b = -b;
	dist = a + b;

	if(s >= dist && (s - dist) % 2 == 0)
		printf("Yes\n");
	else
		printf("No\n");

	return 0;
}

